'use server'

import { revalidatePath } from 'next/cache'

export async function toggleNotificationPreference(userId: string, currentPreference: boolean): Promise<boolean> {
  const newPreference = !currentPreference

  // Simulate database update
  console.log(`Toggling notification for user ${userId}: ${currentPreference} -> ${newPreference}`)

  // Revalidate the current page to refresh the UI
  revalidatePath('/')

  return newPreference
}

